CREATE TABLE avis_core_v2.crypto_assets (
 asset_id text PRIMARY KEY, currency_code varchar(25) UNIQUE NOT NULL, name varchar(200) NOT NULL,
 icon_url text, market_rank integer, market_data jsonb NOT NULL DEFAULT '{}', source text NOT NULL,
 observed_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE avis_core_v2.crypto_asset_networks (
 asset_id text NOT NULL REFERENCES avis_core_v2.crypto_assets, network varchar(32) NOT NULL,
 contract_address varchar(256), decimals smallint CHECK(decimals BETWEEN 0 AND 18),
 approved boolean NOT NULL DEFAULT false, verified_at timestamptz,
 PRIMARY KEY(asset_id,network)
);
CREATE TABLE avis_core_v2.crypto_wallet_keys (
 address_id bigint PRIMARY KEY REFERENCES avis_core_v2.user_deposit_addresses,
 encrypted_key jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE avis_core_v2.crypto_activations (
 user_id bigint NOT NULL REFERENCES avis_core_v2.sovereign_users, asset_id text NOT NULL,
 network varchar(32) NOT NULL, account_id uuid NOT NULL REFERENCES avis_core_v2.ledger_accounts,
 created_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(user_id,asset_id,network), FOREIGN KEY(asset_id,network) REFERENCES avis_core_v2.crypto_asset_networks
);
CREATE TABLE avis_core_v2.crypto_security_cards (
 card_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sort_order integer UNIQUE NOT NULL,
 name varchar(200) NOT NULL, symbol varchar(25) NOT NULL,
 mode varchar(10) NOT NULL DEFAULT 'DEMO' CHECK(mode IN ('DEMO','REAL')),
 state varchar(20) NOT NULL DEFAULT 'DRAFT' CHECK(state IN ('DRAFT','CONVERTED','DEPLOYED','BOOKED')),
 dossier jsonb NOT NULL, conversion_code varchar(66),
 security_id uuid REFERENCES avis_core_v2.portfolio_securities, position_id uuid REFERENCES avis_core_v2.portfolio_positions,
 user_id bigint REFERENCES avis_core_v2.sovereign_users, network varchar(32),
 wallet_address_id bigint REFERENCES avis_core_v2.user_deposit_addresses,
 hub_address varchar(256), contract_address varchar(256),
 token_quantity numeric(36,18) NOT NULL DEFAULT 0 CHECK(token_quantity>=0 AND token_quantity<>'NaN'::numeric),
 source_quantity numeric(36,18) NOT NULL DEFAULT 0 CHECK(source_quantity>=0 AND source_quantity<>'NaN'::numeric),
 journal_id uuid REFERENCES avis_core_v2.ledger_journals,
 version integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now()
);
SELECT n,CASE WHEN n=1 THEN 'AVISPay PLC' ELSE 'Demo security '||lpad(n::text,2,'0') END,
 CASE WHEN n=1 THEN 'aAVISP' ELSE 'DEMO'||lpad(n::text,2,'0') END,
 jsonb_build_object('assetType',CASE WHEN n=1 THEN 'STOCK' ELSE 'SECURITY' END,'currency','CHF',
 'assetValue','100000000','issuedVolume','100000000','faceValue','1','marginHaircutBps',1500,'tradingFeeBps',10,
 'goldGramsPerToken1e6',0,'source','Owner crypto section example','demo',true)
FROM generate_series(1,10) AS n;
CREATE TABLE avis_core_v2.crypto_chain_actions (
 action_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), card_id uuid REFERENCES avis_core_v2.crypto_security_cards,
 user_id bigint NOT NULL REFERENCES avis_core_v2.sovereign_users, network varchar(32) NOT NULL,
 address_id bigint NOT NULL REFERENCES avis_core_v2.user_deposit_addresses, action_type varchar(40) NOT NULL,
 instruction jsonb NOT NULL, review_hash varchar(64) NOT NULL,
 status varchar(16) NOT NULL DEFAULT 'REVIEW' CHECK(status IN ('REVIEW','SIGNED','SUBMITTED','CONFIRMED','FAILED','EXPIRED')),
 reservations jsonb NOT NULL DEFAULT '[]', signed_transaction text, tx_hash varchar(128), receipt jsonb, journal_id uuid REFERENCES avis_core_v2.ledger_journals,
 created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT now()+interval '15 minutes',
 UNIQUE(network,tx_hash)
);
CREATE UNIQUE INDEX crypto_one_card_action ON avis_core_v2.crypto_chain_actions(card_id)
 WHERE card_id IS NOT NULL AND status IN ('REVIEW','SIGNED','SUBMITTED');
CREATE TABLE avis_core_v2.crypto_rolling_channels (
 channel_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), card_id uuid NOT NULL REFERENCES avis_core_v2.crypto_security_cards,
 user_id bigint NOT NULL REFERENCES avis_core_v2.sovereign_users, chain_channel varchar(78) NOT NULL,
 settlement_asset varchar(25) NOT NULL CHECK(settlement_asset IN ('AG','AGi')),
 security_amount numeric(36,18) NOT NULL CHECK(security_amount>0 AND security_amount<>'NaN'::numeric),
 gross_value numeric(36,18) NOT NULL CHECK(gross_value>0 AND gross_value<>'NaN'::numeric),
 state varchar(24) NOT NULL DEFAULT 'CONFIGURED', sequence_id bigint NOT NULL DEFAULT 0,
 cash_fees numeric(36,18) NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(card_id,chain_channel)
);

-- Public metadata snapshot; approval is an explicit administrator action. No holdings are seeded.
